#!/usr/bin/env python3
"""
ABRAXAS FINAL FIX SCRIPT
Run from project root: python3 fix_final.py

Fixes:
  lib/auth.ts                    — TypeScript Session cast error
  types/next-auth.d.ts           — proper Session/JWT type extensions
  tailwind.config.js             — content array fix
  next.config.js                 — Supabase image domains + webpack
  components/LanguageSelector.tsx— flag + dropdown language switcher
  components/TerminalArena.tsx   — LanguageSelector wired into header
  .env.local.example             — all auth + Solana vars
  README.md                      — complete professional docs
"""
import base64, os, sys

if not os.path.exists("components"):
    print("Run from project root")
    sys.exit(1)

FILES = {
    "lib/auth.ts": "",
    "types/next-auth.d.ts": "",
    "tailwind.config.js": "",
    "next.config.js": "",
    "components/LanguageSelector.tsx": "",
    "components/TerminalArena.tsx": "",
    ".env.local.example": "",
    "README.md": "",
}

for path, enc in FILES.items():
    # Create directory if needed
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    content = base64.b64decode(enc).decode("utf-8")
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(content)
    print(f"FIXED  {path} ({len(content.splitlines())} lines)")

# Remove old temp scripts
for tmp in ["fix_issuance.py", "fix_engine.py", "fix_all.py"]:
    if os.path.exists(tmp):
        os.remove(tmp)
        print(f"REMOVED  {tmp}")

print("\nAll done. Run:")
print("  npm run build")
print("  git add -A && git commit -m \"fix: auth.ts types, LanguageSelector, README, configs\"")
print("  git push origin main")
